<style scoped>
.dropdown-enter-active,
.dropdown-leave-active {
    transition: all .35s ease;
    overflow: hidden;
}

.dropdown-enter-from,
.dropdown-leave-to {
    opacity: 0;
    max-height: 0;
    transform: translateY(-10px);
}

.dropdown-enter-to,
.dropdown-leave-from {
    opacity: 1;
    max-height: 500px;
    transform: translateY(0);
}

/* Animasi item satu-satu */
.dropdown-item {
    opacity: 0;
    transform: translateX(-12px);
    animation: dropdownItem .35s forwards;
}

.dropdown-item:nth-child(1) {
    animation-delay: .05s;
}

.dropdown-item:nth-child(2) {
    animation-delay: .12s;
}

.dropdown-item:nth-child(3) {
    animation-delay: .19s;
}

.dropdown-item:nth-child(4) {
    animation-delay: .26s;
}

.dropdown-item:nth-child(5) {
    animation-delay: .33s;
}

@keyframes dropdownItem {
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-thumb{
    background:#6d28d9;
    border-radius:999px;
}

::-webkit-scrollbar-track{
    background:#111;
}

body{
    background:#09090B;
}

table{
    border-collapse:collapse;
}

input::placeholder{
    color:#71717A;
}

button{
    transition:.3s;
}

button:hover{
    transform:translateY(-2px);
}

aside{
    box-shadow:
        0 0 80px rgba(139,92,246,.08);
}

section{

    box-shadow:
        inset 0 1px rgba(255,255,255,.05),
        0 20px 60px rgba(0,0,0,.25);

}

@keyframes floating{

    0%{
        transform:translateY(0px);
    }

    50%{
        transform:translateY(-10px);
    }

    100%{
        transform:translateY(0px);
    }

}

button[class*="fixed"]{

    animation:floating 3s ease infinite;

}

@media(max-width:1024px){

    .grid{

        gap:20px;

    }

}

@media(max-width:768px){

    h1{

        font-size:2rem;

    }

}

@media(max-width:640px){

    .rounded-\[32px\]{

        border-radius:24px;

    }

}

/* Premium Scrollbar */
.scroll-premium {
    scrollbar-width: thin;
    scrollbar-color: #ff2d3d transparent;
}

.scroll-premium::-webkit-scrollbar {
    width: 8px;
}

.scroll-premium::-webkit-scrollbar-track {
    background: transparent;
    margin: 8px 0;
}

.scroll-premium::-webkit-scrollbar-thumb {
     background: linear-gradient(
        to bottom,
        #ff6b6b,
        #ff2d3d,
        #dc2626
    );
    border-radius: 999px;
    border: 2px solid transparent;
    background-clip: content-box;
    transition: .25s;
}

.scroll-premium::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(
        to bottom,
        #ff8787,
        #ff4d5a,
        #ef4444
    );
    background-clip: content-box;
}

.scroll-premium::-webkit-scrollbar-corner {
    background: transparent;
}
</style>